  afterEach(() => {
    cleanupFixture(fixture);
  });

  it('renders a page through a layout with a {{{body}}} placeholder', () => {
    fixture = createFixture(
      { 'post.md': '---\ntitle: First Post\n---\n\nHello **world**.' },
      {
        'layouts/default.hbs':
          '<html><head><title>{{title}}</title></head><body>{{{body}}}</body></html>',
      }
