import { readdirSync } from 'fs';
import { join } from 'path';

export function listMarkdownFiles(dir: string): string[] {
  const files: string[] = [];
  const entries = readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...listMarkdownFiles(fullPath));
    } else if (entry.isFile() && entry.name.endsWith('.md')) {
      files.push(fullPath);
    }
  }
  return files;
}

import { Page } from './page';

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
}

export interface Plugin {
  name: string;
  onStart?(context: PluginContext): void;
  beforeBuild?(context: PluginContext): void;
  onFile?(page: Page, context: PluginContext): Page | void;
  afterBuild?(context: PluginContext, pages: Page[]): void;
  onEnd?(context: PluginContext): void;
}

export function isPlugin(value: unknown): value is Plugin {
  if (value === null || typeof value !== 'object') return false;
  const candidate = value as Partial<Plugin>;
  return (
    typeof candidate.name === 'string' &&
    (typeof candidate.onStart === 'function' ||
      typeof candidate.beforeBuild === 'function' ||
      typeof candidate.onFile === 'function' ||
      typeof candidate.afterBuild === 'function' ||
      typeof candidate.onEnd === 'function')
  );
}

import { Page, pageFromFile } from '../page';
import { Plugin } from '../plugin';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  onFile(page: Page): Page | void {
    if (!page.filePath) return;
    return pageFromFile(page.filePath);
  }
}

import { mkdirSync, writeFileSync } from 'fs';
import { join } from 'path';
import { Page } from '../page';
import { Plugin, PluginContext } from '../plugin';
import { TemplateEngine, loadTemplates } from '../engine';
import { indexHtml, pageHtml } from '../templates';

export class TemplatePlugin implements Plugin {
  name = 'template';

  private engine: TemplateEngine | null = null;

  onStart(context: PluginContext): void {
    this.reload(context);
  }

  beforeBuild(context: PluginContext): void {
    this.reload(context);
  }

  onFile(page: Page, _context: PluginContext): Page {
    page.html = this.renderPage(page);
    return page;
  }

  afterBuild(context: PluginContext, pages: Page[]): void {
    mkdirSync(context.outputDir, { recursive: true });
    for (const page of pages) {
      const html = this.renderPage(page);
      writeFileSync(join(context.outputDir, `${page.slug}.html`), html, 'utf8');
    }
    const index = this.engine ? this.engine.renderIndex(pages) : indexHtml(pages);
    writeFileSync(join(context.outputDir, 'index.html'), index, 'utf8');
  }

  private renderPage(page: Page): string {
    return this.engine ? this.engine.renderPage(page) : pageHtml(page);
  }

  private reload(context: PluginContext): void {
    this.engine = loadTemplates(context.templatesDir);
  }
}

import chokidar, { FSWatcher } from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import { Plugin, PluginContext } from '../plugin';

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  readonly wss: WebSocketServer = new WebSocketServer({ noServer: true });
  watcher: FSWatcher | null = null;

  private rebuildFn: (() => void) | null = null;
  private readyResolve!: () => void;
  private readyReject!: (err: Error) => void;
  private readonly readyPromise: Promise<void>;

  constructor() {
    this.readyPromise = new Promise<void>((resolve, reject) => {
      this.readyResolve = resolve;
      this.readyReject = reject;
    });
  }

  setRebuild(fn: () => void): void {
    this.rebuildFn = fn;
  }

  onStart(context: PluginContext): void {
    this.watcher = chokidar.watch([context.contentDir, context.templatesDir], { ignoreInitial: true });
    this.watcher.on('change', this.rebuild);
    this.watcher.on('add', this.rebuild);
    this.watcher.on('unlink', this.rebuild);
    this.watcher.on('addDir', this.rebuild);
    this.watcher.on('unlinkDir', this.rebuild);
    this.watcher.on('ready', () => this.readyResolve());
    this.watcher.on('error', (err: Error) => this.readyReject(err));
  }

  ready(): Promise<void> {
    return this.readyPromise;
  }

  close(): Promise<void> {
    if (!this.watcher) return Promise.resolve();
    return this.watcher.close();
  }

  private readonly rebuild = (): void => {
    try {
      if (this.rebuildFn) this.rebuildFn();
      this.notifyClients();
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      process.stderr.write(`Rebuild error: ${message}\n`);
    }
  };

  private notifyClients(): void {
    for (const client of this.wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        try {
          client.send('reload');
        } catch {
          // client may have closed between the readyState check and send
        }
      }
    }
  }
}

import { existsSync } from 'fs';
import { dirname, join, resolve } from 'path';
import { isPlugin, Plugin } from './plugin';
import { DevServerPlugin } from './plugins/dev-server';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';

const CONFIG_FILENAMES = ['ssg.config.ts', 'ssg.config.js', 'ssg.config.cjs'];

const BUILTIN_PLUGINS: Record<string, () => Plugin> = {
  markdown: () => new MarkdownPlugin(),
  template: () => new TemplatePlugin(),
  'dev-server': () => new DevServerPlugin(),
  'live-reload': () => new DevServerPlugin(),
};

export function findConfigFile(baseDir: string = process.cwd()): string | null {
  for (const name of CONFIG_FILENAMES) {
    const candidate = join(baseDir, name);
    if (existsSync(candidate)) return candidate;
  }
  return null;
}

function loadModule(configPath: string): unknown {
  const loaded = require(configPath) as unknown;
  if (loaded !== null && typeof loaded === 'object' && 'default' in loaded) {
    return (loaded as { default: unknown }).default;
  }
  return loaded;
}

function extractPluginEntries(value: unknown): unknown[] {
  if (Array.isArray(value)) return value;
  if (value !== null && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    if (Array.isArray(record.plugins)) return record.plugins;
    if (record.plugins !== undefined && record.plugins !== null) return [record.plugins];
    return [record];
  }
  return [];
}

function resolvePluginEntry(entry: unknown, baseDir: string): Plugin | null {
  if (typeof entry === 'string') return resolvePluginName(entry, baseDir);

  let candidate: unknown = entry;
  if (typeof entry === 'function') {
    try {
      candidate = new (entry as new () => unknown)();
    } catch {
      try {
        candidate = (entry as () => unknown)();
      } catch {
        return null;
      }
    }
  }

  if (candidate !== null && typeof candidate === 'object' && isPlugin(candidate)) {
    const plugin = candidate as Plugin;
    if (plugin.name.length === 0) {
      const source = entry as { name?: string };
      return { ...plugin, name: source.name || 'unnamed' };
    }
    return plugin;
  }
  return null;
}

function resolvePluginName(name: string, baseDir: string): Plugin | null {
  const builtin = BUILTIN_PLUGINS[name];
  if (builtin) return builtin();

  const bases = [join(baseDir, 'plugins', name), join(baseDir, name)];
  const seen = new Set<string>();
  for (const base of bases) {
    for (const suffix of ['', '.ts', '.js', '.cjs', '/index.ts', '/index.js']) {
      const target = base + suffix;
      if (seen.has(target)) continue;
      seen.add(target);
      if (!existsSync(target)) continue;
      const loaded = loadModule(target);
      const resolved = resolvePluginEntry(loaded, dirname(target));
      if (resolved) return resolved;
    }
  }
  return null;
}

export function loadPlugins(configPath?: string): Plugin[] {
  const resolvedPath = configPath ? resolve(configPath) : findConfigFile();
  if (!resolvedPath || !existsSync(resolvedPath)) return [];
  try {
    const value = loadModule(resolvedPath);
    const entries = extractPluginEntries(value);
    const plugins: Plugin[] = [];
    for (const entry of entries) {
      const plugin = resolvePluginEntry(entry, dirname(resolvedPath));
      if (plugin) plugins.push(plugin);
    }
    return plugins;
  } catch {
    return [];
  }
}

import { basename, extname } from 'path';
import { Page } from './page';
import { Plugin, PluginContext } from './plugin';
import { loadPlugins } from './config';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import { listMarkdownFiles } from './files';

export interface SsgOptions {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  plugins?: Plugin[];
}

function defaultPlugins(): Plugin[] {
  return [new MarkdownPlugin(), new TemplatePlugin()];
}

function buildPipeline(extra: Plugin[] | undefined): Plugin[] {
  const pipeline = defaultPlugins()
    .concat(loadPlugins())
    .concat(extra ?? []);
  const names = new Set<string>();
  const unique: Plugin[] = [];
  for (const plugin of pipeline) {
    if (names.has(plugin.name)) continue;
    names.add(plugin.name);
    unique.push(plugin);
  }
  return unique;
}

export function createEngine(options: SsgOptions): SsgEngine {
  return new SsgEngine(options);
}

export class SsgEngine {
  private readonly plugins: Plugin[];
  private readonly context: PluginContext;

  constructor(options: SsgOptions) {
    this.context = {
      contentDir: options.contentDir,
      outputDir: options.outputDir,
      templatesDir: options.templatesDir,
    };
    this.plugins = buildPipeline(options.plugins);
  }

  get pipeline(): Plugin[] {
    return this.plugins;
  }

  start(): void {
    for (const plugin of this.plugins) {
      plugin.onStart?.(this.context);
    }
  }

  build(): Page[] {
    for (const plugin of this.plugins) {
      plugin.beforeBuild?.(this.context);
    }

    const files = listMarkdownFiles(this.context.contentDir);
    const pages: Page[] = [];
    for (const file of files) {
      let page: Page = {
        slug: basename(file, extname(file)),
        title: '',
        date: '',
        tags: [],
        contentHtml: '',
        filePath: file,
      };
      for (const plugin of this.plugins) {
        const result = plugin.onFile?.(page, this.context);
        if (result) page = result;
      }
      pages.push(page);
    }
    pages.sort((a, b) => b.date.localeCompare(a.date));

    for (const plugin of this.plugins) {
      plugin.afterBuild?.(this.context, pages);
    }
    for (const plugin of this.plugins) {
      plugin.onEnd?.(this.context);
    }

    return pages;
  }
}

