it('runs every lifecycle hook on every plugin in order', () => {
  fixture = createFixture({ 'a.md': '# A' });
  const order: string[] = [];
  const make = (name: string): Plugin => ({
    name,
    onStart: () => order.push(`${name}:onStart`),
    beforeBuild: () => order.push(`${name}:beforeBuild`),
    onFile: (page) => {
      order.push(`${name}:onFile`);
      return page;
    },
    afterBuild: () => order.push(`${name}:afterBuild`),
    onEnd: () => order.push(`${name}:onEnd`),
  });

  const engine = createEngine({
    contentDir: fixture.contentDir,
    outputDir: fixture.outputDir,
    templatesDir: fixture.templatesDir,
    plugins: [make('custom')],
  });
  engine.start();
  engine.build();

  expect(order.filter((entry) => entry.endsWith(':onStart'))).toEqual(['template:onStart', 'custom:onStart']);
  expect(order.filter((entry) => entry.endsWith(':beforeBuild'))).toEqual(['template:beforeBuild', 'custom:beforeBuild']);
  expect(order.filter((entry) => entry.endsWith(':onFile'))).toEqual([
    'markdown:onFile',
    'template:onFile',
    'custom:onFile',
  ]);
  expect(order.filter((entry) => entry.endsWith(':afterBuild'))).toEqual(['template:afterBuild', 'custom:afterBuild']);
  expect(order.filter((entry) => entry.endsWith(':onEnd'))).toEqual(['custom:onEnd']);
});

